/* Numerical Lab: model classes are independent of the DOM. */
class Expression {
  constructor(source) {
    this.source=source; this.tokens=source.match(/(?:\d+\.?\d*|\.\d+)(?:e[+-]?\d+)?|[a-zA-Z]+|[()+\-*/^]/g)||[];
    if(this.tokens.join('')!==source.replace(/\s/g,'')) throw new Error('สมการมีอักขระที่ไม่รองรับ');
    this.index=0; this.tree=this.sum();
    if(this.index!==this.tokens.length) throw new Error('รูปแบบสมการไม่ถูกต้อง ใช้ * สำหรับการคูณ');
  }
  peek(){return this.tokens[this.index];}
  sum(){let a=this.product();while(['+','-'].includes(this.peek())){const op=this.tokens[this.index++];a=[op,a,this.product()];}return a;}
  product(){let a=this.unary();while(['*','/'].includes(this.peek())){const op=this.tokens[this.index++];a=[op,a,this.unary()];}return a;}
  unary(){if(['+','-'].includes(this.peek())){const op=this.tokens[this.index++];return ['unary',op,this.unary()];}return this.power();}
  power(){let a=this.atom();if(this.peek()==='^'){this.index++;a=['^',a,this.unary()];}return a;}
  atom(){const t=this.tokens[this.index++];if(t===undefined)throw new Error('กรุณาใส่สมการให้ครบ');
    if(t==='('){const a=this.sum();if(this.tokens[this.index++]!==')')throw new Error('วงเล็บไม่ครบ');return a;}
    if(!Number.isNaN(Number(t)))return Number(t);
    if(['x','y','pi','e'].includes(t))return t;
    if(['sin','cos','tan','exp','log','sqrt','abs'].includes(t)){if(this.tokens[this.index++]!=='(')throw new Error('ฟังก์ชันต้องมีวงเล็บ เช่น sin(x)');const a=this.sum();if(this.tokens[this.index++]!==')')throw new Error('วงเล็บไม่ครบ');return ['fn',t,a];}
    throw new Error('รองรับเฉพาะ x, y, pi, e และฟังก์ชันในคู่มือ');
  }
  evaluate(x,y=0){const visit=n=>{if(typeof n==='number')return n;if(typeof n==='string')return ({x,y,pi:Math.PI,e:Math.E})[n];const [op,a,b]=n;if(op==='fn')return Math[a](visit(b));if(op==='unary')return (a==='-'?-1:1)*visit(b);const l=visit(a),r=visit(b);return ({'+':()=>l+r,'-':()=>l-r,'*':()=>l*r,'/':()=>l/r,'^':()=>l**r})[op]();};return visit(this.tree);}
  checked(x,y=0){const v=this.evaluate(x,y);if(!Number.isFinite(v))throw new Error('ฟังก์ชันให้ค่าที่ไม่เป็นจำนวนจริงหรือมีค่าสูงเกินไปในช่วงนี้');return v;}
}
class NumericalMethod {
  constructor(expression,params){this.expression=expression;this.params=params;this.steps=[];this.converged=false;this.reason='';}
  f(x,y){return this.expression.checked(x,y);}
  finish(value,error,converged,reason){this.value=value;this.error=error;this.converged=converged;this.reason=reason;return this;}
}
class Bisection extends NumericalMethod {
  solve(){let {a,b,tolerance,maxIterations}=this.params;if(a>=b)throw new Error('ค่า a ต้องน้อยกว่าค่า b');let fa=this.f(a),fb=this.f(b);
    for(const [x,fx] of [[a,fa],[b,fb]])if(fx===0){this.steps.push({a,b,x,fx,error:0});return this.finish(x,0,true,'พบรากที่ขอบช่วง');}
    if(Math.sign(fa)===Math.sign(fb))throw new Error('Bisection ต้องมี f(a) และ f(b) คนละเครื่องหมาย ลองช่วง [1, 2] สำหรับตัวอย่างแรก');
    for(let i=0;i<maxIterations;i++){const x=(a+b)/2,fx=this.f(x),error=(b-a)/2;this.steps.push({a,b,x,fx,error});if(Math.abs(fx)<=tolerance||error<=tolerance)return this.finish(x,Math.abs(fx),true,'ถึงค่าความคลาดเคลื่อนที่กำหนด');if(Math.sign(fa)!==Math.sign(fx)){b=x;fb=fx;}else{a=x;fa=fx;}}
    const s=this.steps.at(-1);return this.finish(s.x,Math.abs(s.fx),false,'ถึงจำนวนรอบสูงสุด');
  }
}
class NewtonRaphson extends NumericalMethod {
  solve(){let {x0:x,tolerance,maxIterations}=this.params;
    for(let i=0;i<maxIterations;i++){const fx=this.f(x);if(Math.abs(fx)<=tolerance){if(!this.steps.length)this.steps.push({from:x,x,fx,slope:0,error:0});return this.finish(x,Math.abs(fx),true,'Residual ถึงเกณฑ์ที่กำหนด');}const h=1e-5*Math.max(1,Math.abs(x));const slope=(this.f(x+h)-this.f(x-h))/(2*h);if(Math.abs(slope)<1e-12)throw new Error('ความชันใกล้ศูนย์ Newton ไม่สามารถเดินต่อได้ ลองค่าตั้งต้นอื่น');const next=x-fx/slope;if(!Number.isFinite(next)||Math.abs(next)>1e12)throw new Error('ค่าประมาณสูงเกินไป ลองเปลี่ยนค่าตั้งต้น');const nextFx=this.f(next);this.steps.push({from:x,x:next,fx:nextFx,slope,error:Math.abs(next-x)});x=next;if(Math.abs(nextFx)<=tolerance)return this.finish(x,Math.abs(nextFx),true,'Residual ถึงเกณฑ์ที่กำหนด');}
    return this.finish(x,Math.abs(this.f(x)),false,'ถึงจำนวนรอบสูงสุด');
  }
}
class Secant extends NumericalMethod {
  solve(){let {x0:a,x1:b,tolerance,maxIterations}=this.params;if(a===b)throw new Error('ค่า x₀ และ x₁ ต้องต่างกัน');for(let i=0;i<maxIterations;i++){const fa=this.f(a),fb=this.f(b);if(Math.abs(fb)<=tolerance){if(!this.steps.length)this.steps.push({a,b,x:b,fx:fb,error:0});return this.finish(b,Math.abs(fb),true,'Residual ถึงเกณฑ์ที่กำหนด');}if(Math.abs(fb-fa)<1e-14)throw new Error('ค่าฟังก์ชันสองจุดใกล้กันเกินไป ลองค่าตั้งต้นอื่น');const x=b-fb*(b-a)/(fb-fa);if(!Number.isFinite(x)||Math.abs(x)>1e12)throw new Error('ค่าประมาณสูงเกินไป ลองเปลี่ยนค่าตั้งต้น');const fx=this.f(x);this.steps.push({a,b,x,fx,error:Math.abs(x-b)});if(Math.abs(fx)<=tolerance)return this.finish(x,Math.abs(fx),true,'Residual ถึงเกณฑ์ที่กำหนด');a=b;b=x;}const s=this.steps.at(-1);return this.finish(s.x,Math.abs(s.fx),false,'ถึงจำนวนรอบสูงสุด');}
}
class Quadrature extends NumericalMethod {
  constructor(expression,params,simpson=false){super(expression,params);this.simpson=simpson;}
  integrate(n,record=false){const {a,b}=this.params,h=(b-a)/n;let total=0;const width=this.simpson?2:1;for(let i=0;i<n;i+=width){const left=a+i*h,right=left+width*h,mid=(left+right)/2;const area=this.simpson?(right-left)/6*(this.f(left)+4*this.f(mid)+this.f(right)):(right-left)/2*(this.f(left)+this.f(right));total+=area;if(record)this.steps.push({a:left,b:right,x:right,area,total,error:0});}return total;}
  solve(){const {a,b,n}=this.params;if(a>=b)throw new Error('ค่า a ต้องน้อยกว่าค่า b');if(this.simpson&&n%2)throw new Error('Simpson ต้องใช้จำนวนช่วงย่อยเป็นเลขคู่');const coarse=this.integrate(n,true),fine=this.integrate(n*2);return this.finish(coarse,Math.abs(fine-coarse),true,'แบ่งช่วงและรวมพื้นที่ครบแล้ว');}
}
class EulerMethod extends NumericalMethod {
  solve(){const {x0,y0,end,n}=this.params;if(end<=x0)throw new Error('x ปลายทางต้องมากกว่า x₀');const h=(end-x0)/n;let x=x0,y=y0;this.initial={x,y};for(let i=0;i<n;i++){const slope=this.f(x,y),next=y+h*slope;const nextX=x0+(i+1)*h;if(!Number.isFinite(next)||Math.abs(next)>1e12)throw new Error('คำตอบเพิ่มขึ้นสูงเกินไป ลองลดช่วงหรือเพิ่มจำนวนช่วงย่อย');this.steps.push({fromX:x,fromY:y,x:nextX,y:next,slope,error:Math.abs(h*slope)});x=nextX;y=next;}let refined=y0;for(let i=0;i<2*n;i++)refined+=(h/2)*this.f(x0+i*h/2,refined);return this.finish(y,Math.abs(refined-y),true,'คำนวณถึง x ปลายทางแล้ว');}
}
const METHODS={
  bisection:{name:'Bisection',mode:'root',model:Bisection,title:'แบ่งครึ่ง เพื่อเข้าใกล้ราก',text:'เลือกครึ่งช่วงที่ฟังก์ชันเปลี่ยนเครื่องหมาย แล้วทำซ้ำ ช่วงค้นหาจะเล็กลงทุกครั้ง',formula:'xₘ = (a + b) / 2',fields:[['a','ขอบซ้าย a',1],['b','ขอบขวา b',2],['tolerance','Tolerance ε',0.000001],['maxIterations','จำนวนรอบสูงสุด',50]],columns:[['a','a'],['b','b'],['x','ค่าประมาณ x'],['fx','f(x)'],['error','ครึ่งความกว้างช่วง']]},
  newton:{name:'Newton–Raphson',mode:'root',model:NewtonRaphson,title:'เดินตามเส้นสัมผัส',text:'ใช้ความชันของฟังก์ชันประมาณตำแหน่งรากครั้งถัดไป ในห้องทดลองนี้คำนวณอนุพันธ์ด้วยผลต่างกลาง',formula:'xₙ₊₁ = xₙ − f(xₙ) / f′(xₙ)',fields:[['x0','ค่าตั้งต้น x₀',1.5],['tolerance','Tolerance ε',0.000001],['maxIterations','จำนวนรอบสูงสุด',50]],columns:[['from','x ก่อนหน้า'],['slope','ความชัน f′(x)'],['x','ค่าประมาณ x'],['fx','f(x)'],['error','|Δx|']]},
  secant:{name:'Secant',mode:'root',model:Secant,title:'สองจุด บอกทางสู่ราก',text:'ลากเส้นผ่านจุดสองจุดบนกราฟ ใช้จุดตัดแกน x เป็นค่าประมาณใหม่ โดยไม่ต้องหาอนุพันธ์',formula:'xₙ₊₁ = xₙ − f(xₙ)(xₙ − xₙ₋₁) / (f(xₙ) − f(xₙ₋₁))',fields:[['x0','ค่าตั้งต้น x₀',1],['x1','ค่าตั้งต้น x₁',2],['tolerance','Tolerance ε',0.000001],['maxIterations','จำนวนรอบสูงสุด',50]],columns:[['a','xₙ₋₁'],['b','xₙ'],['x','ค่าประมาณ x'],['fx','f(x)'],['error','|Δx|']]},
  trapezoid:{name:'Trapezoidal',mode:'integral',title:'รวมพื้นที่สี่เหลี่ยมคางหมู',text:'แบ่งช่วงเป็นส่วนเล็ก ๆ แล้วแทนพื้นที่ใต้กราฟด้วยสี่เหลี่ยมคางหมู ความละเอียดมากขึ้นมักให้ผลที่แม่นขึ้น',formula:'Aᵢ = h · (f(xᵢ) + f(xᵢ₊₁)) / 2',fields:[['a','ขอบซ้าย a',0],['b','ขอบขวา b',3.141592653589793],['n','จำนวนช่วงย่อย n',12]],columns:[['a','ขอบซ้าย'],['b','ขอบขวา'],['area','พื้นที่ช่วงนี้'],['total','พื้นที่สะสม']]},
  simpson:{name:'Simpson’s ⅓',mode:'integral',title:'โค้งพาราโบลา ประมาณพื้นที่',text:'ใช้พาราโบลาผ่านสามจุดแทนกราฟในทุกคู่ของช่วงย่อย เหมาะกับฟังก์ชันเรียบ และต้องมีจำนวนช่วงเป็นเลขคู่',formula:'Aᵢ = h · (f(xᵢ) + 4f(xᵢ₊₁) + f(xᵢ₊₂)) / 3',fields:[['a','ขอบซ้าย a',0],['b','ขอบขวา b',3.141592653589793],['n','จำนวนช่วงย่อย n',12]],columns:[['a','ขอบซ้าย'],['b','ขอบขวา'],['area','พื้นที่ช่วงนี้'],['total','พื้นที่สะสม']]},
  euler:{name:'Euler Method',mode:'ode',model:EulerMethod,title:'ก้าวเล็ก ๆ ตามความชัน',text:'เริ่มจากจุดที่รู้ค่า y แล้วก้าวไปทีละ h ตามความชัน dy/dx ลองเพิ่มจำนวนช่วงย่อยเพื่อสังเกตผล',formula:'yₙ₊₁ = yₙ + h · f(xₙ, yₙ)',fields:[['x0','ค่าเริ่มต้น x₀',0],['y0','ค่าเริ่มต้น y₀',0.5],['end','x ปลายทาง',2],['n','จำนวนช่วงย่อย n',20]],columns:[['x','x'],['y','ค่าประมาณ y'],['slope','ความชัน'],['error','|Δy|']]}
};
const PRESETS={root:[['x^3 - x - 2','x³ − x − 2'],['cos(x) - x','cos(x) − x'],['x^2 - 2','x² − 2']],integral:[['sin(x)','sin(x)'],['x^2','x²'],['exp(-x^2)','exp(−x²)']],ode:[['y - x^2 + 1','y − x² + 1'],['y','y'],['-2*y','−2y']]};
class PlotRenderer {
  constructor(canvas){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.result=null;new ResizeObserver(()=>this.draw()).observe(canvas);}
  setResult(result,key){this.result=result;this.key=key;this.fit();}
  fit(){if(!this.result)return;const r=this.result,p=r.params,mode=METHODS[this.key].mode;let xs=mode==='root'?r.steps.flatMap(s=>[s.a,s.b,s.from,s.x].filter(Number.isFinite)):mode==='ode'?[p.x0,p.end]:[p.a,p.b];let min=Math.min(...xs),max=Math.max(...xs);if(max-min<.5){min-=.5;max+=.5;}let pad=(max-min)*.2;this.bounds={minX:min-pad,maxX:max+pad};let ys=[0];if(mode==='ode')ys.push(p.y0,...r.steps.map(s=>s.y));else for(let i=0;i<=200;i++){const y=r.expression.evaluate(this.bounds.minX+(this.bounds.maxX-this.bounds.minX)*i/200);if(Number.isFinite(y))ys.push(y);}ys.sort((a,b)=>a-b);let lo=ys[0],hi=ys.at(-1);if(hi-lo<.1){lo-=1;hi+=1;}pad=(hi-lo)*.13;this.bounds.minY=lo-pad;this.bounds.maxY=hi+pad;this.draw();}
  niceStep(range){const rough=range/6,power=10**Math.floor(Math.log10(rough)),ratio=rough/power;return (ratio>5?10:ratio>2?5:ratio>1?2:1)*power;}
  draw(stepIndex=this.stepIndex||0){this.stepIndex=stepIndex;if(!this.result)return;const c=this.canvas,ctx=this.ctx,dpr=window.devicePixelRatio||1,w=c.clientWidth,h=c.clientHeight;if(!w||!h)return;c.width=w*dpr;c.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);const b=this.bounds,m={left:51,right:25,top:24,bottom:33};this.map={X:x=>m.left+(x-b.minX)/(b.maxX-b.minX)*(w-m.left-m.right),Y:y=>h-m.bottom-(y-b.minY)/(b.maxY-b.minY)*(h-m.top-m.bottom),inverseX:px=>b.minX+(px-m.left)/(w-m.left-m.right)*(b.maxX-b.minX)};const {X,Y}=this.map;
    ctx.font='9px Manrope, sans-serif';ctx.lineWidth=1;const grid=(axis,min,max,step)=>{for(let n=Math.ceil(min/step)*step;n<=max+step*1e-6;n+=step){ctx.beginPath();ctx.strokeStyle=Math.abs(n)<step*1e-5?'#d5cede':'#f0edf5';if(axis==='x'){ctx.moveTo(X(n),m.top);ctx.lineTo(X(n),h-m.bottom);}else{ctx.moveTo(m.left,Y(n));ctx.lineTo(w-m.right,Y(n));}ctx.stroke();ctx.fillStyle='#b4aabd';const label=Math.abs(n)<1e-10?'0':Number(n.toPrecision(3)).toString();ctx.textAlign=axis==='x'?'center':'right';ctx.fillText(label,axis==='x'?X(n):m.left-11,axis==='x'?h-m.bottom+17:Y(n)+3);}};grid('x',b.minX,b.maxX,this.niceStep(b.maxX-b.minX));grid('y',b.minY,b.maxY,this.niceStep(b.maxY-b.minY));ctx.fillStyle='#aea2bf';ctx.textAlign='right';ctx.fillText('x',w-m.right+10,Y(0)-7);ctx.fillText(METHODS[this.key].mode==='ode'?'y':'f(x)',m.left-9,m.top-9);
    ctx.save();ctx.beginPath();ctx.rect(m.left,m.top,w-m.left-m.right,h-m.top-m.bottom);ctx.clip();const r=this.result,s=r.steps[stepIndex],mode=METHODS[this.key].mode;
    const line=(points,color,width=1.7,dash=[])=>{ctx.strokeStyle=color;ctx.lineWidth=width;ctx.setLineDash(dash);ctx.beginPath();let started=false;for(const [x,y] of points){if(!Number.isFinite(y)){started=false;continue;}const py=Y(y);if(Math.abs(py)>h*20){started=false;continue;}if(started)ctx.lineTo(X(x),py);else{ctx.moveTo(X(x),py);started=true;}}ctx.stroke();ctx.setLineDash([]);};
    const dot=(x,y,color,size=4)=>{ctx.beginPath();ctx.arc(X(x),Y(y),size+3,0,2*Math.PI);ctx.fillStyle='#ffffff';ctx.fill();ctx.beginPath();ctx.arc(X(x),Y(y),size,0,2*Math.PI);ctx.fillStyle=color;ctx.fill();};
    if(mode==='root'){
      if(this.key==='bisection'){ctx.fillStyle='#7858d60c';ctx.fillRect(X(s.a),m.top,X(s.b)-X(s.a),h-m.top-m.bottom);for(const x of [s.a,s.b])line([[x,b.minY],[x,b.maxY]],'#bcadd5',1,[4,4]);}
      if(this.key==='newton'){const y=r.expression.evaluate(s.from);line([[s.from,y],[s.x,0]],'#dda467',1.8,[5,4]);dot(s.from,y,'#dda467');}
      if(this.key==='secant'){const fa=r.expression.evaluate(s.a),fb=r.expression.evaluate(s.b);line([[s.a,fa],[s.b,fb],[s.x,0]],'#dda467',1.8,[5,4]);dot(s.a,fa,'#dda467',3);dot(s.b,fb,'#dda467',3);}
      line([[s.x,0],[s.x,s.fx]],'#6cad93',1,[3,3]);
    }
    if(mode==='integral'){for(let j=0;j<=stepIndex;j++){const q=r.steps[j];ctx.beginPath();ctx.moveTo(X(q.a),Y(0));if(this.key==='simpson'){const mid=(q.a+q.b)/2,fa=r.f(q.a),fm=r.f(mid),fb=r.f(q.b);for(let i=0;i<=24;i++){const t=i/24,y=fa*(2*t-1)*(t-1)+fm*4*t*(1-t)+fb*t*(2*t-1);ctx.lineTo(X(q.a+t*(q.b-q.a)),Y(y));}}else{ctx.lineTo(X(q.a),Y(r.f(q.a)));ctx.lineTo(X(q.b),Y(r.f(q.b)));}ctx.lineTo(X(q.b),Y(0));ctx.closePath();ctx.fillStyle=j===stepIndex?'#7858d644':'#7858d61a';ctx.fill();ctx.strokeStyle='#b5a2df';ctx.lineWidth=.7;ctx.stroke();}}
    if(mode!=='ode'){const points=[];for(let i=0;i<=650;i++){const x=b.minX+(b.maxX-b.minX)*i/650;points.push([x,r.expression.evaluate(x)]);}line(points,'#805bd8',2.6);if(mode==='root'){dot(s.x,s.fx,'#4ea889');dot(s.x,0,'#4ea889',3);ctx.fillStyle='#4a997b';ctx.font='10px Manrope';ctx.textAlign='center';ctx.fillText('x ≈ '+s.x.toFixed(4),X(s.x),Y(0)+30);}}
    else{const all=[[r.initial.x,r.initial.y],...r.steps.map(q=>[q.x,q.y])];line(all,'#ded6ef',2,[4,4]);const shown=all.slice(0,stepIndex+2);line(shown,'#805bd8',2.5);shown.forEach(([x,y])=>dot(x,y,'#a88bd9',2));dot(s.x,s.y,'#4ea889');}
    ctx.restore();this.canvas.setAttribute('aria-label',mode==='ode'?`ขั้นตอน ${stepIndex+1}: x=${s.x}, y=${s.y}`:`ขั้นตอน ${stepIndex+1}: x=${s.x}, ${mode==='root'?'f(x)='+s.fx:'พื้นที่สะสม='+s.total}`);
  }
}
class NumericalLabApp {
  constructor(){this.key='bisection';this.result=null;this.step=0;this.timer=null;this.plot=new PlotRenderer(document.getElementById('plot'));this.bind();this.selectMethod(this.key);this.registerTools();}
  $(id){return document.getElementById(id);}
  bind(){document.querySelectorAll('[data-mode]').forEach(btn=>btn.addEventListener('click',()=>this.selectMethod(Object.keys(METHODS).find(k=>METHODS[k].mode===btn.dataset.mode))));this.$('experimentForm').addEventListener('submit',e=>{e.preventDefault();this.calculate();});this.$('preset').addEventListener('change',()=>{if(this.$('preset').value!=='custom'){this.$('expression').value=this.$('preset').value;this.applyPresetBounds();this.calculate();}});this.$('expression').addEventListener('input',()=>{this.$('preset').value='custom';});this.$('resetButton').addEventListener('click',()=>this.selectMethod(this.key));this.$('stepSlider').addEventListener('input',e=>{this.pause();this.setStep(Number(e.target.value)-1);});this.$('playButton').addEventListener('click',()=>this.timer?this.pause():this.play());this.$('previousButton').addEventListener('click',()=>{this.pause();this.setStep(this.step-1);});this.$('nextButton').addEventListener('click',()=>{this.pause();this.setStep(this.step+1);});this.$('speed').addEventListener('change',()=>{if(this.timer){this.pause();this.play();}});this.$('fitButton').addEventListener('click',()=>this.plot.fit());this.$('downloadButton').addEventListener('click',()=>this.download());this.$('guideButton').addEventListener('click',()=>this.$('guideDialog').showModal());this.$('closeGuide').addEventListener('click',()=>this.$('guideDialog').close());this.$('plot').addEventListener('pointermove',e=>this.tooltip(e));this.$('plot').addEventListener('pointerleave',()=>{this.$('plotTooltip').hidden=true;});}
  selectMethod(key){this.pause();this.key=key;const m=METHODS[key],mode=m.mode;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));const labels={root:'หารากของสมการ',integral:'การหาปริพันธ์',ode:'สมการเชิงอนุพันธ์'};this.$('crumb').textContent=labels[mode];this.$('pageTitle').innerHTML=({root:'เห็นภาพของ<span>คำตอบ</span>',integral:'มองพื้นที่<span>ใต้กราฟ</span>',ode:'ติดตาม<span>การเปลี่ยนแปลง</span>'})[mode];this.$('pageSubtitle').textContent=({root:'สำรวจการหารากของสมการ ผ่านกราฟและการคำนวณทีละขั้นตอน',integral:'ประมาณปริพันธ์ด้วยการแบ่งช่วง แล้วดูพื้นที่ที่สะสมทีละส่วน',ode:'สำรวจคำตอบของสมการเชิงอนุพันธ์ ด้วยการก้าวตามความชัน'})[mode];this.$('methodTabs').innerHTML='';Object.entries(METHODS).filter(([,v])=>v.mode===mode).forEach(([k,v],i)=>{const b=document.createElement('button');b.className='method-tab'+(k===key?' active':'');b.setAttribute('role','tab');b.setAttribute('aria-selected',String(k===key));b.innerHTML=`<span>0${i+1}</span>${v.name}`;b.addEventListener('click',()=>this.selectMethod(k));this.$('methodTabs').append(b);});this.$('preset').innerHTML='';for(const [value,label] of [...PRESETS[mode],['custom','กำหนดสมการเอง']]){const option=document.createElement('option');option.value=value;option.textContent=label;this.$('preset').append(option);}this.$('expression').value=PRESETS[mode][0][0];this.$('expressionLabel').textContent=mode==='ode'?'ฟังก์ชัน f(x, y)':'ฟังก์ชัน f(x)';this.$('formulaPrefix').textContent=mode==='ode'?'dy/dx =':'ƒ(x) =';this.$('parameterFields').innerHTML='';for(const [name,label,value] of m.fields){const wrap=document.createElement('div');wrap.className='parameter'+(m.fields.length===3&&name===m.fields.at(-1)[0]?' full':'');const l=document.createElement('label');l.htmlFor='param-'+name;l.textContent=label;const input=document.createElement('input');input.type='number';input.id='param-'+name;input.name=name;input.step=['n','maxIterations'].includes(name)?'1':'any';input.value=value;input.required=true;wrap.append(l,input);this.$('parameterFields').append(wrap);}this.$('conceptTitle').textContent=m.title;this.$('conceptText').textContent=m.text;this.$('conceptFormula').textContent=m.formula;this.$('plotBadge').textContent=m.name.toUpperCase()+' METHOD';this.$('graphLegend').innerHTML=mode==='ode'?'<span><i class="legend-line"></i> คำตอบ Euler</span><span><i class="legend-line green"></i> จุดปัจจุบัน</span><span><i class="legend-line dashed"></i> ขั้นตอนถัดไป</span>':`<span><i class="legend-line"></i> ฟังก์ชัน f(x)</span><span><i class="legend-line green"></i> ${mode==='root'?'ค่าประมาณราก':'พื้นที่สะสม'}</span><span><i class="legend-line ${key==='bisection'?'dashed':'orange'}"></i> ${mode==='integral'?'พื้นที่ช่วงย่อย':key==='bisection'?'ขอบเขต [a, b]':'เส้นประมาณ'}</span>`;this.calculate();}
  applyPresetBounds(){if(METHODS[this.key].mode!=='root')return;const expr=this.$('expression').value;const pair=expr==='cos(x) - x'?[0,1]:[1,2];for(const [name,val] of [['a',pair[0]],['b',pair[1]],['x0',pair[0]],['x1',pair[1]]])if(this.$('param-'+name))this.$('param-'+name).value=val;}
  readParams(){const params={};for(const [name] of METHODS[this.key].fields){const raw=this.$('param-'+name).value;if(raw.trim()==='')throw new Error('กรุณากรอกค่าตั้งต้นให้ครบ');const v=Number(raw);if(!Number.isFinite(v))throw new Error('ค่าตั้งต้นต้องเป็นจำนวนที่ถูกต้อง');if(['maxIterations','n'].includes(name)&&(!Number.isInteger(v)||v<1||v>500))throw new Error('จำนวนรอบและช่วงย่อยต้องเป็นจำนวนเต็ม 1–500');if(name==='tolerance'&&(v<1e-12||v>1))throw new Error('Tolerance ต้องอยู่ระหว่าง 10⁻¹² และ 1');if(Math.abs(v)>1e12)throw new Error('ค่าตั้งต้นสูงเกินไป');params[name]=v;}return params;}
  calculate(){this.pause();try{const expr=new Expression(this.$('expression').value);if(METHODS[this.key].mode!=='ode'&&expr.tokens.includes('y'))throw new Error('หมวดนี้ใช้ตัวแปร x เท่านั้น');const params=this.readParams(),m=METHODS[this.key];const result=(m.mode==='integral'?new Quadrature(expr,params,this.key==='simpson'):new m.model(expr,params)).solve();this.result=result;this.$('formError').hidden=true;this.$('plotExpression').textContent=(m.mode==='ode'?'dy/dx = ':'f(x) = ')+expr.source;this.$('plotCaption').textContent=m.mode==='root'?'ช่วงค้นหาและค่าประมาณในแต่ละรอบ':m.mode==='integral'?'พื้นที่สะสมจากขอบซ้ายไปขอบขวา':'จุดคำตอบที่คำนวณจากความชันในแต่ละก้าว';this.plot.setResult(result,this.key);this.$('stepSlider').max=result.steps.length;this.renderResults();this.renderTable();this.setStep(0);return true;}catch(error){this.$('formError').textContent=error.message;this.$('formError').hidden=false;return false;}}
  format(v){if(!Number.isFinite(v))return '—';if(v===0)return '0.000000';if(Math.abs(v)<.00001||Math.abs(v)>=1e6)return v.toExponential(3);return v.toFixed(6);}
  renderResults(){const r=this.result,mode=METHODS[this.key].mode;this.$('answerLabel').innerHTML=(mode==='root'?'ค่ารากโดยประมาณ':mode==='integral'?'ค่าปริพันธ์โดยประมาณ':'ค่า y ปลายทาง')+' <span>↗</span>';this.$('answer').textContent=this.format(r.value);this.$('answerDetail').textContent=mode==='root'?'คำตอบสุดท้ายจากทุกขั้นตอน':mode==='integral'?`ช่วง [${r.params.a}, ${Number(r.params.b.toFixed(4))}]`:`เมื่อ x = ${r.params.end}`;this.$('iterations').textContent=String(r.steps.length).padStart(2,'0');this.$('errorLabel').innerHTML=(mode==='root'?'Residual |f(x)|':'ผลต่างเมื่อเพิ่มช่วง 2 เท่า')+' <span>◎</span>';this.$('errorValue').textContent=this.format(r.error);this.$('errorDetail').textContent=mode==='root'?'ค่ายิ่งเล็ก ยิ่งเข้าใกล้คำตอบ':'เปรียบเทียบ n กับ 2n ไม่ใช่ error จริง';this.$('resultStatus').textContent=r.converged?(mode==='root'?'ลู่เข้าแล้ว':'คำนวณครบแล้ว'):'ยังไม่ลู่เข้า';this.$('statusDetail').textContent=r.reason;this.$('resultStatus').closest('article').classList.toggle('warn',!r.converged);}
  renderTable(){const r=this.result,columns=METHODS[this.key].columns;this.$('tableCount').textContent=r.steps.length+' รอบ';this.$('tableHead').innerHTML='<tr><th>รอบที่</th>'+columns.map(([,label])=>`<th>${label}</th>`).join('')+'</tr>';this.$('tableBody').innerHTML=r.steps.map((s,i)=>`<tr tabindex="0" aria-label="เลือกขั้นตอน ${i+1}" data-step="${i}"><td><span class="iteration-pill">${String(i+1).padStart(2,'0')}</span></td>${columns.map(([key])=>`<td>${this.format(s[key])}</td>`).join('')}</tr>`).join('');this.$('tableBody').querySelectorAll('tr').forEach(row=>{const choose=()=>{this.pause();this.setStep(Number(row.dataset.step));};row.addEventListener('click',choose);row.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose();}});});}
  setStep(index){if(!this.result)return;this.step=Math.max(0,Math.min(index,this.result.steps.length-1));this.$('stepSlider').value=this.step+1;this.$('stepCounter').textContent=String(this.step+1).padStart(2,'0')+' / '+String(this.result.steps.length).padStart(2,'0');this.$('previousButton').disabled=this.step===0;this.$('nextButton').disabled=this.step===this.result.steps.length-1;this.plot.draw(this.step);this.$('tableBody').querySelectorAll('tr').forEach((row,i)=>{row.classList.toggle('selected',i===this.step);row.setAttribute('aria-current',String(i===this.step));});const s=this.result.steps[this.step],mode=METHODS[this.key].mode;this.$('stepExplanation').textContent=mode==='root'?`รอบ ${this.step+1} → ค่าประมาณ x = ${this.format(s.x)} · f(x) = ${this.format(s.fx)}`:mode==='integral'?`ช่วง ${this.step+1} → พื้นที่ช่วงนี้ ${this.format(s.area)} · พื้นที่สะสม ${this.format(s.total)}`:`ก้าว ${this.step+1} → x = ${this.format(s.x)} · y ≈ ${this.format(s.y)} · ความชัน ${this.format(s.slope)}`;}
  play(){if(!this.result)return;if(this.step===this.result.steps.length-1)this.setStep(0);this.$('playButton').textContent='Ⅱ';this.$('playButton').setAttribute('aria-label','หยุดการเล่น');this.timer=setInterval(()=>{if(this.step>=this.result.steps.length-1){this.pause();return;}this.setStep(this.step+1);if(this.step===this.result.steps.length-1)this.pause();},Number(this.$('speed').value));}
  pause(){clearInterval(this.timer);this.timer=null;this.$('playButton').textContent='▶';this.$('playButton').setAttribute('aria-label','เล่นขั้นตอนการคำนวณ');}
  tooltip(e){if(!this.result||!this.plot.map)return;const rect=this.$('plot').getBoundingClientRect(),px=e.clientX-rect.left,x=this.plot.map.inverseX(px);if(METHODS[this.key].mode==='ode'){this.$('plotTooltip').hidden=true;return;}const y=this.result.expression.evaluate(x);if(!Number.isFinite(y))return;const t=this.$('plotTooltip');t.textContent=`x: ${x.toFixed(3)} · f(x): ${y.toFixed(3)}`;t.style.left=Math.max(0,Math.min(px+12,rect.width-190))+'px';t.style.top=Math.max(0,e.clientY-rect.top-32)+'px';t.hidden=false;}
  download(){if(!this.result)return;const columns=METHODS[this.key].columns;const rows=[['Iteration',...columns.map(([key])=>key)],...this.result.steps.map((s,i)=>[i+1,...columns.map(([key])=>s[key])])];const blob=new Blob(['\uFEFF'+rows.map(row=>row.join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`numerical-lab-${this.key}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  registerTools(){if(!document.modelContext?.registerTool)return;this.toolLifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'run_numerical_experiment',title:'Run a numerical experiment',description:'Choose a method, calculate a function, and update the visible graph and iteration table.',inputSchema:{type:'object',properties:{method:{type:'string',enum:Object.keys(METHODS)},expression:{type:'string'},parameters:{type:'object',additionalProperties:{type:'number'}}},required:['method','expression','parameters'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||!Object.hasOwn(METHODS,input.method)||typeof input.expression!=='string'||!input.parameters||typeof input.parameters!=='object')throw new Error('Invalid experiment');const m=METHODS[input.method],params=input.parameters;for(const [name] of m.fields)if(!Object.hasOwn(params,name)||!Number.isFinite(params[name]))throw new Error('Missing or invalid parameter '+name);const expression=new Expression(input.expression);if(m.mode!=='ode'&&expression.tokens.includes('y'))throw new Error('Only x is supported');for(const [name,value] of Object.entries(params)){if(!m.fields.some(([field])=>field===name))throw new Error('Unknown parameter');if(Math.abs(value)>1e12||(['n','maxIterations'].includes(name)&&(!Number.isInteger(value)||value<1||value>500))||(name==='tolerance'&&(value<1e-12||value>1)))throw new Error('Parameter out of range');}const validation=(m.mode==='integral'?new Quadrature(expression,params,input.method==='simpson'):new m.model(expression,params)).solve();this.selectMethod(input.method);this.$('expression').value=input.expression;this.$('preset').value='custom';for(const [name,value] of Object.entries(params))this.$('param-'+name).value=value;if(!this.calculate())throw new Error(this.$('formError').textContent);return {method:this.key,value:validation.value,error:validation.error,iterations:validation.steps.length,converged:validation.converged};}},{signal:this.toolLifecycle.signal})).catch(()=>{});}catch{}}
}
if(typeof document!=='undefined')window.numericalLab=new NumericalLabApp();
if(typeof module!=='undefined')module.exports={Expression,Bisection,NewtonRaphson,Secant,Quadrature,EulerMethod};
